INSERT INTO exercises (id, name, category, equipment, target, muscle_group, secondary_muscles, instructions_es, image_url, gif_url) VALUES
('3292', 'elevator', 'back', 'body weight', 'upper back', 'shoulders', '{"shoulders","trapezius"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Coloca las manos sobre las caderas o crúzalas frente al pecho. Manteniendo la espalda recta, inclínate lentamente hacia adelante desde la cintura, bajando la parte superior del cuerpo hacia el suelo. Haz una pausa por un momento en la posición más baja, luego sube lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3292-zYmNaoY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3292-zYmNaoY.gif'),
('1332', 'exercise ball alternating arm ups', 'back', 'stability ball', 'lats', 'shoulders', '{"shoulders","core"}', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta. Sujeta una mancuerna en cada mano con las palmas hacia adentro y los brazos extendidos hacia abajo a los lados. Activa el core y levanta lentamente un brazo hacia el hombro, manteniendo el codo ligeramente flexionado. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el movimiento con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1332-EyLrNC2.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1332-EyLrNC2.gif'),
('1333', 'exercise ball back extension with arms extended', 'back', 'stability ball', 'spine', 'glutes', '{"glutes","hamstrings"}', 'Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad. Extiende los brazos rectos hacia adelante, con las palmas hacia abajo. Activa el core y levanta lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta y el cuello alineado con la columna. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1333-PERjVm8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1333-PERjVm8.gif'),
('1334', 'exercise ball back extension with hands behind head', 'back', 'stability ball', 'spine', 'glutes', '{"glutes","hamstrings"}', 'Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él con las caderas apoyadas en el balón. Coloca los pies contra una pared u otra superficie estable para apoyarte. Cruza los brazos detrás de la cabeza, con las manos tocando la parte de atrás de la cabeza. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta las caderas. Haz una pausa breve en la parte alta del movimiento, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1334-o1HGDSq.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1334-o1HGDSq.gif'),
('1335', 'exercise ball back extension with knees off ground', 'back', 'stability ball', 'spine', 'glutes', '{"glutes","hamstrings"}', 'Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1335-WME869U.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1335-WME869U.gif'),
('1336', 'exercise ball back extension with rotation', 'back', 'stability ball', 'spine', 'glutes', '{"glutes","hamstrings"}', 'Comienza tumbado boca abajo sobre el balón de estabilidad, con las caderas apoyadas en el balón y los pies firmemente apoyados en el suelo. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones. Haz una pausa por un momento en la parte superior, luego gira lentamente el torso hacia un lado, manteniendo las caderas y las piernas estables. Vuelve al centro y repite el giro hacia el otro lado. Baja la parte superior del cuerpo de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1336-WVD66ff.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1336-WVD66ff.gif'),
('1744', 'exercise ball dip', 'upper arms', 'stability ball', 'triceps', 'chest', '{"chest","shoulders"}', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Coloca las manos sobre el balón junto a las caderas, con los dedos apuntando hacia adelante. Activa el tríceps y empuja con las manos para levantar el cuerpo del balón, enderezando los brazos. Baja el cuerpo flexionando los codos, manteniéndolos cerca de los costados. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1744-kprile3.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1744-kprile3.gif'),
('1559', 'exercise ball hip flexor stretch', 'upper legs', 'stability ball', 'glutes', 'quadriceps', '{"quadriceps","hamstrings"}', 'Coloca el balón de estabilidad en el suelo y arrodíllate frente a él. Coloca el pie derecho sobre el balón de estabilidad, con la rodilla flexionada en un ángulo de 90 grados. Extiende la pierna izquierda hacia atrás, manteniéndola recta. Inclínate hacia adelante, empujando las caderas hacia el balón de estabilidad, hasta sentir un estiramiento en el flexor de la cadera derecha. Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1559-2LQkNPW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1559-2LQkNPW.gif'),
('1338', 'exercise ball hug', 'back', 'stability ball', 'spine', 'shoulders', '{"shoulders","chest"}', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta. Sujeta el balón de estabilidad con ambas manos, abrazándolo cerca del pecho. Activa los músculos del core y reclínate lentamente hacia atrás, manteniendo la espalda recta y los pies apoyados en el suelo. Continúa reclinándote hacia atrás hasta sentir un estiramiento en los músculos de la espalda. Mantén la posición durante unos segundos, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1338-d7z1Y7V.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1338-d7z1Y7V.gif'),
('1339', 'exercise ball lat stretch', 'back', 'stability ball', 'lats', 'shoulders', '{"shoulders","triceps"}', 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sujeta una mancuerna con una mano y extiende el brazo recto por encima de la cabeza. Inclínate lentamente hacia el lado opuesto, sintiendo un estiramiento en el músculo dorsal. Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial. Repite del otro lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1339-sM84pE4.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1339-sM84pE4.gif'),
('1341', 'exercise ball lower back stretch (pyramid)', 'back', 'stability ball', 'lats', 'glutes', '{"glutes","hamstrings"}', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Camina lentamente hacia adelante con los pies, haciendo rodar el balón por tu espalda hasta que tu zona lumbar quede apoyada sobre el balón. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el core y baja lentamente la parte superior del cuerpo hacia el suelo, permitiendo que tu zona lumbar se estire sobre el balón. Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1341-yU7w7CA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1341-yU7w7CA.gif'),
('1342', 'exercise ball lying side lat stretch', 'back', 'stability ball', 'lats', 'shoulders', '{"shoulders","triceps"}', 'Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el balón de estabilidad. Coloca el brazo de arriba sobre el balón para mantener la estabilidad. Extiende el brazo de arriba por encima de la cabeza y permite que tu torso gire ligeramente. Siente el estiramiento en los músculos dorsales del costado de tu cuerpo. Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1342-rTbyBYV.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1342-rTbyBYV.gif'),
('1382', 'exercise ball on the wall calf raise', 'lower legs', 'dumbbell', 'calves', 'hamstrings', '{"hamstrings","quadriceps"}', 'Ponte de pie con la espalda contra una pared y coloca un balón de ejercicio entre tu zona lumbar y la pared. Coloca los pies separados a la altura de los hombros, con la punta de los pies hacia adelante. Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados. Levanta los talones del suelo, llevando el peso de tu cuerpo hacia la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1382-xo6sENf.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1382-xo6sENf.gif'),
('3241', 'exercise ball on the wall calf raise (tennis ball between ankles)', 'lower legs', 'dumbbell', 'calves', 'hamstrings', '{"hamstrings","quadriceps"}', 'Ponte de pie frente a una pared con los pies separados a la altura de los hombros. Coloca un balón de ejercicio entre la pared y tu zona lumbar. Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados. Coloca una pelota de tenis entre los tobillos. Levanta los talones del suelo, elevando el cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3241-FY3UdNT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3241-FY3UdNT.gif'),
('3240', 'exercise ball on the wall calf raise (tennis ball between knees)', 'lower legs', 'dumbbell', 'calves', 'quadriceps', '{"quadriceps","hamstrings"}', 'Ponte de pie con la espalda contra una pared y coloca un balón de ejercicio entre tu zona lumbar y la pared. Coloca los pies separados a la altura de los hombros y ligeramente por delante de ti. Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados. Coloca una pelota de tenis entre las rodillas. Levanta los talones del suelo, elevando el cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3240-j74M6Zn.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3240-j74M6Zn.gif'),
('1416', 'exercise ball one leg prone lower body rotation', 'upper legs', 'stability ball', 'glutes', 'hamstrings', '{"hamstrings","quadriceps","core"}', 'Túmbate boca abajo sobre el balón de estabilidad con las caderas apoyadas en el balón y las piernas extendidas rectas detrás de ti. Coloca las manos en el suelo frente a ti para mayor apoyo. Activa los glúteos y el abdomen para estabilizar el cuerpo. Levanta lentamente una pierna del suelo, manteniéndola recta y paralela al piso. Gira la pierna hacia afuera, alejándola del cuerpo, mientras mantienes las caderas y la parte superior del cuerpo estables. Haz una pausa al final de la rotación, luego regresa lentamente la pierna a la posición inicial. Repite la rotación con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1416-M72BExt.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1416-M72BExt.gif'),
('1417', 'exercise ball one legged diagonal kick hamstring curl', 'upper legs', 'stability ball', 'glutes', 'hamstrings', '{"hamstrings","calves"}', 'Comienza acostado sobre la espalda con las piernas extendidas y los talones apoyados sobre el balón de estabilidad. Coloca los brazos a los lados del cuerpo para mantener el equilibrio. Activa los glúteos y el abdomen para levantar las caderas del suelo, formando una línea recta desde los hombros hasta los talones. Dobla la rodilla derecha y llévala hacia el pecho, manteniendo la pierna izquierda extendida y el pie en flexión. Lleva la pierna derecha en diagonal a través del cuerpo, extendiéndola por completo y activando los isquiotibiales. Regresa lentamente la pierna derecha a la posición inicial, manteniendo el control y el equilibrio. Repite el movimiento con la pierna izquierda, alternando los lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1417-GOJKFfO.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1417-GOJKFfO.gif'),
('1296', 'exercise ball pike push up', 'chest', 'stability ball', 'pectorals', 'shoulders', '{"shoulders","triceps","core"}', 'Comienza en posición de flexión de brazos con las manos en el suelo y las espinillas apoyadas sobre el balón de estabilidad. Activa el core y levanta las caderas hacia el techo, haciendo rodar el balón hacia las manos. Mantén las piernas rectas y el cuerpo en posición de pica, formando una V invertida. Dobla los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo la cabeza alineada con las manos. Empuja con las manos y extiende los brazos para volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1296-sVvXT5J.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1296-sVvXT5J.gif'),
('1343', 'exercise ball prone leg raise', 'back', 'stability ball', 'spine', 'abdominals', '{"abdominals","glutes"}', 'Túmbate boca abajo sobre una esterilla con las piernas extendidas y los dedos de los pies apoyados sobre el balón de estabilidad. Coloca las manos en el suelo, separadas a la altura de los hombros, y activa el abdomen. Manteniendo las piernas rectas, levántalas lentamente del suelo, usando la zona lumbar y los glúteos para elevarlas tan alto como sea posible. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1343-lCKm4Rs.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1343-lCKm4Rs.gif'),
('1560', 'exercise ball seated hamstring stretch', 'upper legs', 'stability ball', 'hamstrings', 'glutes', '{"glutes","lower back"}', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Haz rodar el balón lentamente hacia adelante, caminando con los pies hacia afuera hasta que la parte superior de la espalda quede apoyada sobre el balón y las piernas queden extendidas rectas frente a ti. Coloca las manos en las caderas para mayor apoyo. Activa el core y baja lentamente la parte superior del cuerpo hacia el suelo, manteniendo la espalda recta y el pecho elevado. Detente cuando sientas un estiramiento en los isquiotibiales y mantén la posición durante 20-30 segundos. Regresa lentamente a la posición inicial empujando con los talones y usando los isquiotibiales para volver a subir. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1560-yRYyfdA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1560-yRYyfdA.gif'),
('1745', 'exercise ball seated triceps stretch', 'upper arms', 'stability ball', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sostén una mancuerna con una mano y extiende el brazo recto por encima de la cabeza. Dobla el codo y baja la mancuerna detrás de la cabeza, manteniendo el brazo cerca de la oreja. Mantén el estiramiento durante unos segundos, luego regresa a la posición inicial. Repite con el otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1745-7ePTw4B.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1745-7ePTw4B.gif'),
('1746', 'exercise ball supine triceps extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia el techo. Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas. Haz una pausa por un momento, luego sube la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1746-Gm2Uv1z.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1746-Gm2Uv1z.gif'),
('1747', 'ez bar french press on exercise ball', 'upper arms', 'ez barbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate sobre un balón de ejercicio y sostén una barra EZ con agarre prono. Extiende los brazos rectos hacia arriba, manteniendo los codos cerca de la cabeza. Baja lentamente la barra detrás de la cabeza doblando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1747-CFN9P8G.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1747-CFN9P8G.gif'),
('3010', 'ez bar lying bent arms pullover', 'back', 'ez barbell', 'lats', 'triceps', '{"triceps","chest"}', 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sostén la barra EZ con agarre prono (palmas hacia afuera) y las manos separadas a la altura de los hombros. Extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos. Baja la barra describiendo un arco detrás de la cabeza, manteniendo la ligera flexión en los codos. Haz una pausa breve, luego regresa la barra a la posición inicial invirtiendo el movimiento del arco. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3010-nDK1HJ0.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3010-nDK1HJ0.gif'),
('1748', 'ez bar lying close grip triceps extension behind head', 'upper arms', 'ez barbell', 'triceps', 'shoulders', '{"shoulders"}', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sostén la barra EZ con agarre cerrado, palmas hacia arriba, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1748-6CKUx7o.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1748-6CKUx7o.gif'),
('1344', 'ez bar reverse grip bent over row', 'back', 'ez barbell', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo. Tira de la barra EZ hacia la parte baja del pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte superior, luego baja lentamente la barra EZ a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1344-G8dXpNG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1344-G8dXpNG.gif'),
('1682', 'ez bar seated close grip concentration curl', 'upper arms', 'ez barbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con los pies apoyados en el suelo y sostén una barra EZ con agarre supino. Apoya el codo en la parte interna del muslo, justo por encima de la rodilla. Sube la barra curvando el brazo hacia el hombro mientras mantienes el brazo superior inmóvil. Contrae los bíceps en la parte superior del movimiento, luego baja lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1682-Dsfz0Id.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1682-Dsfz0Id.gif'),
('1749', 'ez bar standing french press', 'upper arms', 'ez barbell', 'triceps', 'shoulders', '{"shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre prono. Levanta la barra por encima de la cabeza, extendiendo completamente los brazos. Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1749-1cTf2Ux.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1749-1cTf2Ux.gif'),
('0445', 'ez barbell anti gravity press', 'shoulders', 'ez barbell', 'delts', 'triceps', '{"triceps","chest"}', 'Comienza de pie con los pies separados a la altura de los hombros y sosteniendo la barra EZ con agarre prono. Eleva la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y las palmas hacia adelante. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0445-fprd84i.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0445-fprd84i.gif'),
('1627', 'ez barbell close grip preacher curl', 'upper arms', 'ez barbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco scott y coloca los brazos superiores sobre la almohadilla, sujetando la barra EZ con agarre supino. Apoya los tríceps sobre la almohadilla y extiende los brazos por completo, manteniendo la espalda recta. Sube lentamente la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte alta, apretando los bíceps. Baja la barra a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1627-hacCyUv.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1627-hacCyUv.gif'),
('0446', 'ez barbell close-grip curl', 'upper arms', 'ez barbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento. Sube la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0446-V4ryaZa.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0446-V4ryaZa.gif'),
('0447', 'ez barbell curl', 'upper arms', 'ez barbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba. Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento. Exhala mientras subes la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta, luego inhala mientras bajas lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0447-6TG6x2w.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0447-6TG6x2w.gif'),
('0448', 'ez barbell decline close grip face press', 'upper arms', 'ez barbell', 'triceps', 'chest', '{"chest","shoulders"}', 'Túmbate en un banco declinado con la cabeza más baja que los pies. Sujeta la barra EZ con agarre cerrado, palmas una frente a la otra. Extiende los brazos rectos por encima del pecho, manteniendo los codos cerca del cuerpo. Baja la barra hacia la frente doblando los codos. Haz una pausa breve, luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0448-DgZQ11d.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0448-DgZQ11d.gif'),
('2186', 'ez barbell decline triceps extension', 'upper arms', 'ez barbell', 'triceps', 'shoulders', '{"shoulders"}', 'Túmbate en un banco declinado con la cabeza más baja que los pies y los pies asegurados. Sostén la barra EZ con agarre prono, manos separadas a la altura de los hombros. Extiende completamente los brazos, manteniendo los codos cerca de la cabeza. Baja la barra lentamente hacia la frente, doblando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2186-CQHoDm0.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2186-CQHoDm0.gif'),
('0449', 'ez barbell incline triceps extension', 'upper arms', 'ez barbell', 'triceps', 'shoulders', '{"shoulders"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y sostén la barra EZ con agarre prono. Extiende completamente los brazos por encima de la cabeza, manteniendo los codos cerca de la cabeza. Baja la barra detrás de la cabeza doblando los codos, manteniendo los brazos superiores inmóviles. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0449-KyLtiLT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0449-KyLtiLT.gif'),
('0450', 'ez barbell jm bench press', 'upper arms', 'ez barbell', 'triceps', 'chest', '{"chest","shoulders"}', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta la barra EZ con agarre prono, ligeramente más ancho que la altura de los hombros. Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0450-hnOYgH3.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0450-hnOYgH3.gif'),
('0451', 'ez barbell reverse grip curl', 'upper arms', 'ez barbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino. Mantén los codos cerca del torso y los brazos superiores inmóviles durante todo el ejercicio. Sube la barra contrayendo los bíceps, mientras exhalas. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Comienza a regresar la barra lentamente a la posición inicial mientras inhalas. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0451-Y5X65IB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0451-Y5X65IB.gif'),
('0452', 'ez barbell reverse grip preacher curl', 'upper arms', 'ez barbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco scott con el pecho apoyado en la almohadilla y los pies planos sobre el suelo. Sujeta la barra EZ con agarre supino, manos separadas a la altura de los hombros. Apoya los brazos superiores en la almohadilla, dejando que los antebrazos cuelguen hacia abajo. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros. Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0452-vBNyir7.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0452-vBNyir7.gif'),
('1458', 'ez barbell seated curls', 'upper arms', 'ez barbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta. Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros. Apoya los brazos superiores en los muslos, dejando que la barra EZ cuelgue frente a ti. Manteniendo los brazos superiores inmóviles, exhala y sube la barra EZ hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra EZ a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1458-jtFKbt5.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1458-jtFKbt5.gif'),
('0453', 'ez barbell seated triceps extension', 'upper arms', 'ez barbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sostén la barra EZ con agarre prono, manos separadas a la altura de los hombros. Levanta la barra por encima de la cabeza, extendiendo completamente los brazos. Manteniendo los brazos superiores inmóviles, baja la barra detrás de la cabeza doblando los codos. Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0453-iaapw0g.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0453-iaapw0g.gif'),
('0454', 'ez barbell spider curl', 'upper arms', 'ez barbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba. Apoya los brazos superiores en un banco scott o en un balón de estabilidad, dejando que los codos cuelguen hacia abajo. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0454-Ye5Qxb0.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0454-Ye5Qxb0.gif'),
('1628', 'ez barbell spider curl', 'upper arms', 'ez barbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba. Apoya los brazos superiores en un banco scott o en un balón de estabilidad, dejando que los codos cuelguen hacia abajo. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1628-2kattbR.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1628-2kattbR.gif'),
('2404', 'ez-bar biceps curl (with arm blaster)', 'upper arms', 'ez barbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba. Coloca los brazos superiores contra el soporte de aislamiento de brazos, manteniéndolos inmóviles durante todo el ejercicio. Manteniendo los codos cerca del cuerpo, exhala y sube la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2404-tJ5nYqo.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2404-tJ5nYqo.gif'),
('2432', 'ez-bar close-grip bench press', 'upper arms', 'ez barbell', 'triceps', 'chest', '{"chest","shoulders"}', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta la barra EZ con agarre cerrado, manos separadas a la altura de los hombros, palmas hacia adelante. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2432-da4cXST.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2432-da4cXST.gif'),
('2741', 'ez-barbell standing wide grip biceps curl', 'upper arms', 'ez barbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, manos más separadas que la altura de los hombros. Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento. Sube la barra hacia los hombros contrayendo los bíceps. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2741-OVTZ65k.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2741-OVTZ65k.gif'),
('2133', 'farmers walk', 'upper legs', 'dumbbell', 'quads', 'calves', '{"calves","forearms","core"}', 'Ponte de pie con una mancuerna en cada mano, palmas hacia los costados. Mantén la espalda recta y los hombros hacia atrás. Da pasos pequeños y controlados hacia adelante, manteniendo una postura erguida. Continúa caminando durante la distancia o el tiempo deseado. Para terminar, deja de caminar y baja con cuidado las mancuernas a los costados.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2133-qPEzJjA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2133-qPEzJjA.gif'),
('0455', 'finger curls', 'lower arms', 'barbell', 'forearms', 'wrist flexors', '{"wrist flexors","grip muscles"}', 'Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Curva lentamente los dedos hacia las palmas, apretando la barra con fuerza. Mantén la contracción por un momento, luego suelta lentamente los dedos hasta la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0455-awG04cF.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0455-awG04cF.gif'),
('3303', 'flag', 'waist', 'body weight', 'abs', 'obliques', '{"obliques","shoulders"}', 'Comienza sujetando un poste vertical con ambas manos, palmas una frente a la otra, y los brazos completamente extendidos. Activa el core y levanta las piernas del suelo, manteniéndolas rectas. Usando la fuerza del core y de la parte superior del cuerpo, levanta las piernas hasta que queden paralelas al suelo. Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3303-pQ0Mx1Z.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3303-pQ0Mx1Z.gif'),
('0456', 'flexion leg sit up (bent knee)', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Al mismo tiempo, levanta las piernas del suelo, doblando las rodillas y llevándolas hacia el pecho. Haz una pausa breve en la parte superior, luego baja lentamente la parte superior del cuerpo y las piernas a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0456-AR0ig3o.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0456-AR0ig3o.gif'),
('0457', 'flexion leg sit up (straight arm)', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors","quadriceps"}', 'Túmbate boca arriba con las piernas extendidas y los brazos rectos por encima de la cabeza. Activando el abdomen, levanta la parte superior del cuerpo del suelo mientras al mismo tiempo levantas las piernas hacia el pecho. Extiende las manos hacia los dedos de los pies mientras levantas la parte superior del cuerpo y las piernas. Haz una pausa breve en la parte superior, luego baja lentamente la parte superior del cuerpo y las piernas a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0457-KZn52RC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0457-KZn52RC.gif'),
('0458', 'floor fly (with barbell)', 'chest', 'barbell', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo. Sostén una barra con agarre prono, brazos extendidos rectos por encima del pecho. Baja lentamente la barra hacia los lados, manteniendo una ligera flexión en los codos. Baja la barra hasta que los brazos queden paralelos al suelo, sintiendo un estiramiento en el pecho. Haz una pausa breve, luego contrae los músculos del pecho para llevar la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0458-neonEDL.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0458-neonEDL.gif'),
('0459', 'flutter kicks', 'upper legs', 'body weight', 'glutes', 'hip flexors', '{"hip flexors","lower abs"}', 'Túmbate boca arriba con las piernas extendidas y las manos a los costados. Activa el core y levanta las piernas del suelo unos 15 centímetros. Manteniendo las piernas rectas, alterna levantando una pierna ligeramente más alto que la otra. Continúa este movimiento de aleteo durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0459-UVo2Qs2.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0459-UVo2Qs2.gif'),
('1472', 'forward jump', 'upper legs', 'body weight', 'quads', 'calves', '{"calves","hamstrings","glutes"}', 'Ponte de pie con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla. Balancea los brazos hacia atrás para generar impulso. Salta hacia adelante de forma explosiva, extendiendo las caderas, las rodillas y los tobillos. Aterriza suavemente sobre la punta de los pies y pasa de inmediato al siguiente salto. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1472-uZKq7lo.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1472-uZKq7lo.gif'),
('3470', 'forward lunge (male)', 'upper legs', 'body weight', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de las caderas y las manos en las caderas. Da un paso grande hacia adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Dobla la rodilla derecha hasta unos 90 grados, manteniendo la rodilla alineada con el tobillo. Empuja con el pie derecho y vuelve a la posición inicial. Repite con la pierna izquierda, alternando los lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3470-kMzUs9Y.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3470-kMzUs9Y.gif'),
('3194', 'frankenstein squat', 'upper legs', 'barbell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra frente al cuerpo con los brazos rectos. Manteniendo la espalda recta, baja el cuerpo flexionando las rodillas y las caderas, como si fueras a sentarte en una silla. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3194-bdWcbaU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3194-bdWcbaU.gif'),
('2429', 'frog crunch', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2429-FFRP97T.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2429-FFRP97T.gif'),
('3301', 'frog planche', 'waist', 'body weight', 'abs', 'shoulders', '{"shoulders","chest","triceps"}', 'Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los pies juntos. Dobla los codos y baja el cuerpo hacia el suelo, manteniendo la espalda recta. Mientras bajas el cuerpo, levanta los pies del suelo y lleva las rodillas hacia el pecho. Mantén esta posición durante unos segundos, luego extiende las piernas de nuevo y empújate hacia arriba a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3301-rQhGcin.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3301-rQhGcin.gif'),
('3296', 'front lever', 'waist', 'body weight', 'abs', 'lats', '{"lats","shoulders","forearms"}', 'Comienza colgado de una barra de dominadas con agarre prono, manos separadas a la altura de los hombros. Activa el core y lleva los omóplatos hacia abajo y atrás. Flexiona las rodillas y llévalas hacia el pecho. Al mismo tiempo, levanta las piernas y extiéndelas rectas frente a ti, manteniendo el cuerpo paralelo al suelo. Mantén esta posición todo el tiempo que puedas, intentando lograr una posición completa de palanca frontal. Para soltar, baja lentamente las piernas y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3296-PkCN2lv.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3296-PkCN2lv.gif'),
('3295', 'front lever reps', 'back', 'body weight', 'upper back', 'core', '{"core","shoulders"}', 'Cuélgate de una barra de dominadas con agarre prono, palmas hacia afuera. Activa el core y lleva los omóplatos hacia abajo y atrás. Manteniendo el cuerpo recto, levanta las piernas hasta que queden paralelas al suelo. Mantén esta posición todo el tiempo que puedas, intentando llegar a 10-20 segundos. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3295-hbY9wqG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3295-hbY9wqG.gif'),
('0464', 'front plank with twist', 'waist', 'body weight', 'abs', 'obliques', '{"obliques","shoulders"}', 'Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies. Activa el core y los glúteos para mantener una posición estable. Gira el torso hacia la derecha, levantando el brazo derecho y extendiéndolo hacia el techo. Mantén las caderas y las piernas estables mientras giras. Mantén la posición por un momento, luego regresa a la posición inicial. Repite el giro hacia el lado izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0464-CosupLu.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0464-CosupLu.gif'),
('3315', 'full maltese', 'waist', 'body weight', 'abs', 'shoulders', '{"shoulders","chest"}', 'Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos rectos hacia los lados. Inclínate lentamente hacia adelante, manteniendo los brazos rectos, hasta que la parte superior del cuerpo quede paralela al suelo. Activa el core y mantén esta posición durante unos segundos. Regresa a la posición inicial empujando con los pies y volviendo a ponerte de pie. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3315-YRaCa5Y.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3315-YRaCa5Y.gif'),
('3299', 'full planche', 'waist', 'body weight', 'abs', 'shoulders', '{"shoulders","chest","triceps"}', 'Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los dedos apuntando hacia adelante. Activa el core y desplaza lentamente el peso hacia adelante, levantando los pies del suelo. Continúa desplazando el peso hacia adelante hasta que el cuerpo quede paralelo al suelo, equilibrándote sobre las manos. Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta. Baja lentamente los pies de nuevo al suelo y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3299-YZ4961r.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3299-YZ4961r.gif'),
('3327', 'full planche push-up', 'chest', 'body weight', 'pectorals', 'shoulders', '{"shoulders","triceps","core"}', 'Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros. Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados. Mientras te bajas, inclina el cuerpo hacia adelante y levanta los pies del suelo, equilibrándote sobre las manos. Continúa bajando el cuerpo hasta que el pecho quede justo por encima del suelo. Empuja con las manos y extiende los brazos para volver a subir el cuerpo a la posición inicial. Mantén una línea recta desde la cabeza hasta los talones durante todo el movimiento. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3327-gw9PqGk.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3327-gw9PqGk.gif'),
('0466', 'gironda sternum chin', 'back', 'body weight', 'lats', 'biceps', '{"biceps","rhomboids","rear deltoids"}', 'Ponte de pie frente a una barra alta con los pies separados a la altura de los hombros. Estira los brazos hacia arriba y agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los dorsales y los bíceps para llevar el pecho hacia la barra, guiando con el esternón. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0466-IL0JUxR.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0466-IL0JUxR.gif'),
('3561', 'glute bridge march', 'upper legs', 'body weight', 'glutes', 'hamstrings', '{"hamstrings","quadriceps"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros. Manteniendo las caderas elevadas, levanta un pie del suelo y lleva la rodilla hacia el pecho. Baja el pie de nuevo al suelo y repite el movimiento con la otra pierna. Continúa alternando las piernas con un movimiento de marcha mientras mantienes la posición de puente. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3561-GibBPPg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3561-GibBPPg.gif'),
('3523', 'glute bridge two legs on bench (male)', 'upper legs', 'body weight', 'glutes', 'hamstrings', '{"hamstrings","core"}', 'Siéntate en el borde de un banco con la espalda apoyada en él y los pies planos sobre el suelo. Coloca las manos en el banco junto a las caderas para mayor apoyo. Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3523-aWedzZX.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3523-aWedzZX.gif'),
('3193', 'glute-ham raise', 'upper legs', 'body weight', 'hamstrings', 'glutes', '{"glutes","lower back"}', 'Ajusta la máquina de extensión de glúteos e isquiotibiales para que se adapte a tu cuerpo. Colócate boca abajo en la máquina con los tobillos asegurados. Coloca las manos sobre el pecho o crúzalas sobre el pecho. Activa los isquiotibiales y los glúteos para levantar la parte superior del cuerpo hacia el techo. Continúa levantando hasta que el cuerpo forme una línea recta desde la cabeza hasta los talones. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3193-Vvwjz6N.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3193-Vvwjz6N.gif'),
('0467', 'gorilla chin', 'waist', 'body weight', 'abs', 'forearms', '{"forearms","biceps"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra de dominadas con agarre prono, ligeramente más ancho que la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y las palmas hacia afuera. Activa el core y tira del cuerpo hacia la barra, llevando la barbilla por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0467-bmwlYvD.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0467-bmwlYvD.gif'),
('0469', 'groin crunch', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors","inner thighs"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0469-mWppALS.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0469-mWppALS.gif'),
('1383', 'hack calf raise', 'lower legs', 'sled machine', 'calves', 'hamstrings', '{"hamstrings","glutes"}', 'Ajusta la máquina de trineo a un peso adecuado. Ponte de pie sobre la máquina de trineo con la punta de los pies en la plataforma y los talones colgando. Sujétate de las asas para mantener el equilibrio. Levanta los talones lo más alto posible empujando con la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1383-2ORFMoR.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1383-2ORFMoR.gif'),
('1384', 'hack one leg calf raise', 'lower legs', 'sled machine', 'calves', 'hamstrings', '{"hamstrings","glutes"}', 'Ajusta la máquina de trineo a un peso adecuado. Ponte de pie sobre la máquina de trineo con un pie, manteniendo el otro pie levantado del suelo. Sujétate de las asas para mantener el equilibrio. Levanta el talón lo más alto posible, elevando el cuerpo sobre la punta del pie. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de pierna y repite el ejercicio.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1384-AxFoqAD.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1384-AxFoqAD.gif'),
('3221', 'half knee bends (male)', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', '{"quadriceps","hamstrings","glutes"}', 'Ponte de pie con los pies separados a la altura de los hombros. Dobla las rodillas y baja el cuerpo como si te fueras a sentar en una silla. Mantén el pecho elevado y el peso en los talones. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3221-ia6kIIl.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3221-ia6kIIl.gif'),
('3202', 'half sit-up (male)', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3202-iQ241UP.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3202-iQ241UP.gif'),
('1511', 'hamstring stretch', 'upper legs', 'body weight', 'hamstrings', 'glutes', '{"glutes"}', 'Ponte de pie con los pies separados a la altura de los hombros. Da un paso adelante con el pie derecho y traslada el peso hacia la pierna derecha. Manteniendo la espalda recta, inclínate lentamente hacia adelante desde las caderas, alcanzando el pie derecho con ambas manos. Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial. Repite del otro lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1511-99rWm7w.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1511-99rWm7w.gif'),
('2139', 'hands bike', 'chest', 'upper body ergometer', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Ajusta la altura del asiento y la posición del manillar a un nivel cómodo. Siéntate en el ergómetro con la espalda recta y los pies sobre los pedales. Sujeta las asas con las manos y coloca los brazos en un ángulo de 90 grados. Comienza a pedalear con las manos, empujando y tirando de las asas con un movimiento controlado. Continúa pedaleando durante el tiempo o el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2139-pAIWRGu.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2139-pAIWRGu.gif'),
('3218', 'hands clasped circular toe touch (male)', 'upper legs', 'body weight', 'glutes', 'hamstrings', '{"hamstrings","quadriceps","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros y las manos entrelazadas frente al pecho. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Baja las manos hacia los dedos de los pies con un movimiento circular, llegando tan lejos como puedas sin forzar. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3218-B5xca8s.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3218-B5xca8s.gif'),
('3215', 'hands reversed clasped circular toe touch (male)', 'upper legs', 'body weight', 'glutes', 'hamstrings', '{"hamstrings","quadriceps","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Extiende las manos hacia abajo y entrelázalas detrás de las piernas. Sube lentamente las manos en un movimiento circular por encima de la cabeza, manteniendo las piernas rectas. Continúa el movimiento circular hasta que las manos toquen los dedos de los pies. Invierte el movimiento y regresa las manos a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3215-yq3GAJX.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3215-yq3GAJX.gif'),
('3302', 'handstand', 'upper arms', 'body weight', 'triceps', 'shoulders', '{"shoulders","core"}', 'Busca un espacio abierto con suficiente espacio para hacer un pino. Coloca las manos en el suelo separadas a la altura de los hombros, con los dedos apuntando hacia adelante. Lanza las piernas hacia la pared, usando el core y los hombros para mantener el equilibrio. Una vez en posición de pino, activa los tríceps para sostener el peso corporal. Mantén el pino el mayor tiempo posible mientras conserves el equilibrio. Para bajar, lleva lentamente las piernas de vuelta al suelo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3302-XooAdhl.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3302-XooAdhl.gif'),
('0471', 'handstand push-up', 'upper arms', 'body weight', 'triceps', 'shoulders', '{"shoulders","chest","core"}', 'Busca una pared y colócate de espaldas a ella, de pie a unos pasos de distancia. Coloca las manos en el suelo separadas a la altura de los hombros y lanza los pies hacia la pared, llegando a una posición de pino. Dobla los codos y baja la cabeza hacia el suelo, manteniendo el cuerpo en línea recta. Empuja con las manos y extiende los brazos para volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0471-rQxwMxO.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0471-rQxwMxO.gif'),
('1764', 'hanging leg hip raise', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors","lower back"}', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas flexionando las caderas y las rodillas hasta que los muslos queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1764-VEcJRo2.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1764-VEcJRo2.gif'),
('0472', 'hanging leg raise', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0472-I3tsCnC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0472-I3tsCnC.gif'),
('1761', 'hanging oblique knee raise', 'waist', 'body weight', 'abs', 'obliques', '{"obliques"}', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las rodillas hacia el pecho, girando el torso hacia un lado mientras lo haces. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite hacia el otro lado, girando el torso en la dirección opuesta. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1761-BaE7O6U.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1761-BaE7O6U.gif'),
('0473', 'hanging pike', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors","shoulders"}', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas hacia la barra, manteniéndolas rectas. Continúa levantando hasta que el cuerpo forme una ''V'', con las piernas paralelas al suelo. Mantén la posición por un momento, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0473-nuBF9MO.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0473-nuBF9MO.gif'),
('0474', 'hanging straight leg hip raise', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas hacia adelante hasta que queden paralelas al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0474-pj0X0tF.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0474-pj0X0tF.gif'),
('0475', 'hanging straight leg raise', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0475-4Ml7QFO.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0475-4Ml7QFO.gif'),
('0476', 'hanging straight twisting leg hip raise', 'waist', 'body weight', 'abs', 'obliques', '{"obliques","hip flexors"}', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las piernas rectas. Activa el core y levanta las piernas hacia el pecho, manteniéndolas rectas. Cuando las piernas queden paralelas al suelo, gira las caderas hacia un lado, llevando las piernas hacia ese lado. Haz una pausa breve y luego vuelve a la posición inicial. Repite el movimiento, pero esta vez gira las caderas hacia el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0476-Q6bvyen.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0476-Q6bvyen.gif'),
('3636', 'high knee against wall', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', '{"quadriceps","hamstrings","glutes","calves"}', 'Ponte de pie frente a una pared con los pies separados a la altura de las caderas. Coloca las manos en la pared para mayor apoyo. Activa el core y levanta la rodilla derecha hacia el pecho, mientras mantienes el pie izquierdo en el suelo. Cambia rápidamente de pierna, llevando la rodilla izquierda hacia el pecho y bajando el pie derecho de nuevo. Continúa alternando las piernas con un movimiento de carrera, llevando las rodillas lo más alto posible. Mantén un ritmo rápido y la parte superior del cuerpo estable durante todo el ejercicio. Repite durante la duración o el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3636-ealLwvX.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3636-ealLwvX.gif'),
('0484', 'hip raise (bent knee)', 'waist', 'body weight', 'abs', 'glutes', '{"glutes","hamstrings"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos a los lados, con las palmas hacia abajo. Activa el core y los glúteos, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0484-196HJGw.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0484-196HJGw.gif'),
('1418', 'hug keens to chest', 'upper legs', 'body weight', 'glutes', 'hamstrings', '{"hamstrings","quadriceps"}', 'Comienza de pie con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla. Al ponerte en cuclillas, lleva las rodillas hacia el pecho y abrázalas con los brazos. Mantén esta posición por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1418-znP9SIh.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1418-znP9SIh.gif'),
('3234', 'hyght dumbbell fly', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders"}', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos. Manteniendo una ligera flexión en los codos, baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3234-P9ZRyLT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3234-P9ZRyLT.gif'),
('0489', 'hyperextension', 'back', 'body weight', 'spine', 'glutes', '{"glutes","hamstrings"}', 'Ajusta el banco de hiperextensiones para que la parte superior de los muslos quede apoyada en la almohadilla y los pies queden asegurados. Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza. Baja la parte superior del cuerpo hacia el suelo manteniendo la espalda recta. Haz una pausa breve en la parte baja, luego eleva la parte superior del cuerpo hasta que quede alineada con las piernas. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0489-zhMwOwE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0489-zhMwOwE.gif'),
('0488', 'hyperextension (on bench)', 'back', 'body weight', 'spine', 'glutes', '{"glutes","hamstrings"}', 'Ajusta el banco de hiperextensiones para que las caderas queden apoyadas cómodamente en la almohadilla y los pies queden asegurados. Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza. Baja lentamente la parte superior del cuerpo hacia el suelo manteniendo la espalda recta. Haz una pausa breve en la parte baja, luego eleva la parte superior del cuerpo hasta que quede alineada con las piernas. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0488-zkgRrbK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0488-zkgRrbK.gif'),
('3289', 'impossible dips', 'upper arms', 'body weight', 'triceps', 'chest', '{"chest","shoulders"}', 'Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo suspendido en el aire. Flexiona las rodillas y cruza los tobillos. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3289-05Cf2v8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3289-05Cf2v8.gif'),
('1471', 'inchworm', 'waist', 'body weight', 'abs', 'shoulders', '{"shoulders","hamstrings"}', 'Comienza de pie con los pies separados a la altura de las caderas. Inclínate hacia adelante desde la cintura y coloca las manos en el suelo frente a ti. Camina con las manos hacia adelante hasta quedar en posición de plancha alta, con el cuerpo en línea recta de la cabeza a los pies. Haz una pausa breve, luego camina con las manos de vuelta hacia los pies, manteniendo las piernas lo más rectas posible. Cuando las manos lleguen a los pies, ponte de pie de nuevo en la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1471-ZgsNQ6d.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1471-ZgsNQ6d.gif'),
('3698', 'inchworm v. 2', 'waist', 'body weight', 'abs', 'shoulders', '{"shoulders","hamstrings"}', 'Comienza de pie con los pies separados a la altura de las caderas. Inclínate hacia adelante desde la cintura y coloca las manos en el suelo frente a ti. Camina con las manos hacia adelante hasta quedar en posición de plancha alta, con el cuerpo en línea recta de la cabeza a los pies. Manteniendo las piernas rectas, camina con los pies hacia las manos, llevando las caderas hacia el techo. Continúa caminando con las manos hacia adelante, repitiendo el movimiento durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3698-TV87DNB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3698-TV87DNB.gif'),
('0490', 'incline close-grip push-up', 'upper arms', 'body weight', 'triceps', 'chest', '{"chest","shoulders"}', 'Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros. Extiende las piernas detrás de ti, apoyándote en la punta de los pies, con el cuerpo formando una línea recta desde la cabeza hasta los talones. Baja el pecho hacia la superficie elevada doblando los codos, manteniéndolos cerca de los costados. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0490-1YB40kg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0490-1YB40kg.gif'),
('0491', 'incline leg hip raise (leg straight)', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate en un banco inclinado con la espalda apoyada plana en el banco y las piernas extendidas rectas frente a ti. Coloca las manos a los lados del banco para apoyarte. Activando el abdomen, levanta las piernas del banco, elevándolas tan alto como puedas mientras las mantienes rectas. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0491-eVxAzgz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0491-eVxAzgz.gif'),
('0492', 'incline push up depth jump', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders","core"}', 'Busca una superficie elevada, como un banco o un escalón, y coloca las manos separadas a la altura de los hombros en el borde. Da un paso hacia atrás con los pies, manteniendo el cuerpo en línea recta desde la cabeza hasta los talones. Baja el pecho hacia el borde de la superficie, doblando los codos y manteniendo el cuerpo alineado. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Salta desde el borde de la superficie, aterrizando suavemente con las rodillas ligeramente flexionadas. Repite la flexión de brazos y el salto en profundidad durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0492-CB8WET1.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0492-CB8WET1.gif'),
('0493', 'incline push-up', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros. Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones. Baja el pecho hacia la superficie elevada doblando los codos, manteniendo el cuerpo en línea recta. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0493-B1EVP9F.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0493-B1EVP9F.gif'),
('3785', 'incline push-up (on box)', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Coloca las manos en el borde de una caja o una superficie elevada, ligeramente más separadas que la altura de los hombros. Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones. Baja el pecho hacia la caja doblando los codos, manteniendo el cuerpo en línea recta. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3785-F7vjXqT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3785-F7vjXqT.gif'),
('0494', 'incline reverse grip push-up', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Coloca las manos en el borde de un banco o una superficie elevada, ligeramente más separadas que la altura de los hombros. Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones. Baja el pecho hacia el banco doblando los codos, manteniéndolos cerca de los costados. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0494-XaaRnRn.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0494-XaaRnRn.gif'),
('3011', 'incline scapula push up', 'chest', 'body weight', 'serratus anterior', 'triceps', '{"triceps","shoulders"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Coloca las manos en el banco, ligeramente más separadas que la altura de los hombros. Coloca los pies en el suelo, separados a la altura de las caderas. Baja el pecho hacia el banco, manteniendo los codos pegados al cuerpo. Mientras bajas, retrae los omóplatos, apretándolos entre sí. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3011-GdMa1ET.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3011-GdMa1ET.gif'),
('0495', 'incline twisting sit-up', 'waist', 'body weight', 'abs', 'obliques', '{"obliques"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo del banco, curvándote hacia adelante. Mientras te incorporas, gira el torso hacia un lado, llevando el codo hacia la rodilla opuesta. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el movimiento, esta vez girando el torso hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0495-9ZGZuOD.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0495-9ZGZuOD.gif'),
('1564', 'intermediate hip flexor and quad stretch', 'upper legs', 'rope', 'quads', 'hamstrings', '{"hamstrings","glutes"}', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Sujétate de un objeto estable para mayor apoyo. Dobla la rodilla derecha y lleva el pie derecho hacia los glúteos, sujetando la cuerda con la mano derecha. Tira lentamente del pie derecho hacia los glúteos, sintiendo un estiramiento en el cuádriceps derecho. Mantén el estiramiento durante 20-30 segundos. Suelta el estiramiento y repite en el lado izquierdo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1564-tFGKm99.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1564-tFGKm99.gif'),
('0496', 'inverse leg curl (bench support)', 'upper legs', 'body weight', 'hamstrings', 'glutes', '{"glutes","calves"}', 'Túmbate boca abajo en un banco con las caderas en el borde y las piernas extendidas rectas detrás de ti. Sujétate del banco para mayor apoyo. Manteniendo la parte superior del cuerpo quieta, dobla las rodillas y curva las piernas hacia los glúteos. Haz una pausa breve en la parte superior, luego extiende lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0496-ms7tjSG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0496-ms7tjSG.gif'),
('2400', 'inverse leg curl (on pull-up cable machine)', 'upper legs', 'body weight', 'hamstrings', 'glutes', '{"glutes","calves"}', 'Ajusta la máquina de cable para que las correas de tobillo estén en el ajuste más bajo. Túmbate boca abajo en el banco con las piernas extendidas y las correas de tobillo sujetas a los pies. Sujétate de las agarraderas del banco para mantener la estabilidad. Dobla las rodillas y curva las piernas hacia los glúteos, contrayendo los isquiotibiales. Haz una pausa breve en la parte superior del movimiento, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2400-0rHfvy9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2400-0rHfvy9.gif'),
('0499', 'inverted row', 'back', 'body weight', 'upper back', 'biceps', '{"biceps","forearms"}', 'Coloca una barra a la altura de la cintura o usa un entrenador de suspensión. Ponte de pie frente a la barra o al entrenador de suspensión, con los pies separados a la altura de los hombros. Agarra la barra o las asas con agarre prono, ligeramente más ancho que la altura de los hombros. Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo. Tira del pecho hacia la barra o las asas, apretando los omóplatos entre sí. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0499-bZGHsAZ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0499-bZGHsAZ.gif'),
('2300', 'inverted row bent knees', 'back', 'body weight', 'upper back', 'biceps', '{"biceps","forearms"}', 'Coloca una barra a la altura de la cintura y túmbate debajo de ella. Agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros. Coloca el cuerpo de manera que los talones queden en el suelo y el cuerpo esté recto. Tira del pecho hacia arriba en dirección a la barra apretando los omóplatos entre sí. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2300-VPPtusI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2300-VPPtusI.gif'),
('2298', 'inverted row on bench', 'back', 'body weight', 'upper back', 'biceps', '{"biceps","forearms"}', 'Coloca un banco a una altura que permita que el cuerpo cuelgue libremente debajo de él. Túmbate boca arriba en el suelo con la cabeza hacia el banco. Estira los brazos hacia arriba y agarra el banco con agarre prono, ligeramente más ancho que la altura de los hombros. Coloca el cuerpo de manera que los talones queden en el suelo y los brazos completamente extendidos. Activa el core y aprieta los omóplatos entre sí mientras tiras del pecho hacia el banco. Haz una pausa breve en la parte superior del movimiento, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2298-Mxa7Cr8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2298-Mxa7Cr8.gif'),
('0497', 'inverted row v. 2', 'back', 'body weight', 'upper back', 'biceps', '{"biceps","forearms"}', 'Coloca una barra a la altura de la cintura en una máquina Smith o usa un entrenador de suspensión. Ponte de pie frente a la barra o al entrenador de suspensión y agárrala con agarre prono, manos separadas a la altura de los hombros. Camina con los pies hacia adelante, inclinándote hacia atrás hasta que el cuerpo quede en un ligero ángulo. Mantén el cuerpo recto y tira del pecho hacia la barra o las asas, apretando los omóplatos entre sí. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0497-uX3sUBz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0497-uX3sUBz.gif'),
('0498', 'inverted row with straps', 'back', 'body weight', 'upper back', 'biceps', '{"biceps","forearms"}', 'Coloca un entrenador de suspensión o correas a la altura del pecho. Ponte de pie frente al punto de anclaje y agarra las asas con agarre prono. Camina con los pies hacia adelante, inclinándote hacia atrás hasta que el cuerpo quede en ángulo. Mantén el cuerpo recto y activa el core. Tira del pecho hacia las asas, apretando los omóplatos entre sí. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0498-jdiExfW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0498-jdiExfW.gif'),
('1419', 'iron cross stretch', 'upper legs', 'body weight', 'glutes', 'hamstrings', '{"hamstrings","quadriceps"}', 'Túmbate boca arriba con los brazos extendidos hacia los lados. Levanta las piernas hacia el techo, manteniéndolas rectas. Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies. Mantén el estiramiento durante unos segundos, luego regresa las piernas a la posición inicial. Repite el estiramiento en el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1419-pZwUsKB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1419-pZwUsKB.gif'),
('1297', 'isometric chest squeeze', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Extiende los brazos rectos frente a ti, paralelos al suelo, con las palmas una frente a la otra. Aprieta los músculos del pecho con la mayor fuerza posible, manteniendo los brazos rectos. Mantén esta posición durante unos segundos, concentrándote en contraer los músculos del pecho. Suelta la contracción y relaja los músculos del pecho. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1297-HbSG1Pw.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1297-HbSG1Pw.gif'),
('0500', 'isometric wipers', 'chest', 'body weight', 'pectorals', 'shoulders', '{"shoulders","triceps","core"}', 'Comienza acostado boca arriba en una esterilla o un banco. Extiende los brazos hacia los lados, perpendiculares al cuerpo. Activa el core y levanta ambas piernas del suelo, manteniéndolas juntas y rectas. Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies mientras mantienes el control. Haz una pausa breve, luego usa el core para llevar las piernas de vuelta a la posición inicial. Repite el movimiento, esta vez bajando las piernas hacia el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0500-11wrviz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0500-11wrviz.gif'),
('0501', 'jack burpee', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', '{"quadriceps","hamstrings","calves","shoulders","triceps","core"}', 'Comienza de pie con los pies separados a la altura de los hombros. Baja el cuerpo a una posición de sentadilla, colocando las manos en el suelo frente a ti. Lanza los pies hacia atrás, aterrizando en posición de flexión de brazos. Realiza una flexión de brazos, bajando el pecho hacia el suelo y luego empujando de nuevo hacia arriba. Salta con los pies hacia adelante, aterrizando en posición de sentadilla. Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza. Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0501-mr7pkqP.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0501-mr7pkqP.gif'),
('3224', 'jack jump (male)', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', '{"quadriceps","calves"}', 'Ponte de pie con los pies juntos y los brazos a los costados. Salta, separando los pies y levantando los brazos por encima de la cabeza. Al aterrizar, salta rápidamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3224-1g5bPpA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3224-1g5bPpA.gif'),
('0507', 'jackknife sit-up', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate boca arriba con las piernas extendidas y los brazos por encima de la cabeza. Activa el core y levanta las piernas y la parte superior del cuerpo al mismo tiempo, llevando las manos hacia los dedos de los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0507-mbkgB44.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0507-mbkgB44.gif'),
('0508', 'janda sit-up', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors","lower back"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0508-1GPHRyK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0508-1GPHRyK.gif'),
('2612', 'jump rope', 'cardio', 'rope', 'cardiovascular system', 'calves', '{"calves","quadriceps","hamstrings","glutes"}', 'Sujeta las asas de la cuerda de saltar con las manos, palmas hacia adentro. Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Balancea la cuerda por encima de la cabeza y salta sobre ella cuando se acerque a los pies. Aterriza suavemente sobre la punta de los pies y repite el salto cuando la cuerda vuelva a pasar. Continúa saltando durante el tiempo o el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2612-e1e76I2.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2612-e1e76I2.gif'),
('0514', 'jump squat', 'upper legs', 'body weight', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Salta de forma explosiva desde el suelo, extendiendo las caderas, las rodillas y los tobillos. Mientras estás en el aire, lleva rápidamente los brazos hacia adelante para mantener el equilibrio. Aterriza suavemente sobre la punta de los pies y pasa de inmediato a la siguiente repetición. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0514-LIlE5Tn.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0514-LIlE5Tn.gif'),
('0513', 'jump squat v. 2', 'upper legs', 'body weight', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Salta de forma explosiva, extendiendo por completo las caderas y las rodillas. Aterriza suavemente sobre la punta de los pies y de inmediato baja el cuerpo de nuevo a una posición de sentadilla. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0513-TDYiji6.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0513-TDYiji6.gif'),
('0517', 'kettlebell advanced windmill', 'waist', 'kettlebell', 'abs', 'obliques', '{"obliques","shoulders"}', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sostén una pesa rusa en la mano derecha, con el brazo extendido por encima de la cabeza y la palma hacia adelante. Gira el pie izquierdo ligeramente hacia la derecha y traslada el peso hacia la pierna izquierda. Dobla la rodilla izquierda y flexiona la cadera, bajando el torso hacia el lado izquierdo. Mantén el brazo derecho extendido por encima de la cabeza y la mirada en la pesa rusa. Mientras bajas el torso, permite que la pierna derecha se enderece y que el pie derecho gire ligeramente. Baja el torso hasta sentir un estiramiento en el isquiotibial izquierdo y que el brazo derecho apunte hacia el suelo. Haz una pausa breve, luego activa el core y empuja con el talón izquierdo para regresar a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0517-Kal9cQQ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0517-Kal9cQQ.gif'),
('0518', 'kettlebell alternating hang clean', 'lower arms', 'kettlebell', 'forearms', 'shoulders', '{"shoulders","traps","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Deja que las pesas rusas cuelguen frente al cuerpo con los brazos completamente extendidos. En un solo movimiento fluido, extiende las caderas de forma explosiva, encoge los hombros y tira de las pesas rusas hacia los hombros. Cuando las pesas rusas alcancen la altura de los hombros, gira las muñecas y atrápalas en posición de descanso, con las palmas hacia adentro y las pesas rusas apoyadas en la parte externa de los antebrazos. Baja las pesas rusas de nuevo a la posición inicial y repite el movimiento con el brazo opuesto. Continúa alternando los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0518-I4tibZG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0518-I4tibZG.gif'),
('0520', 'kettlebell alternating press', 'shoulders', 'kettlebell', 'delts', 'triceps', '{"triceps","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros. Empuja una pesa rusa por encima de la cabeza, extendiendo el brazo por completo. Baja la pesa rusa de nuevo a la altura de los hombros. Repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0520-5KLbZWx.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0520-5KLbZWx.gif'),
('0519', 'kettlebell alternating press on floor', 'chest', 'kettlebell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo. Sostén una pesa rusa en cada mano, con las palmas hacia los pies y los brazos extendidos rectos hacia el techo. Baja una pesa rusa hacia el hombro mientras mantienes la otra pesa rusa extendida recta hacia arriba. Empuja la pesa rusa bajada de vuelta hacia la posición inicial mientras al mismo tiempo bajas la otra pesa rusa hacia el hombro. Continúa alternando el movimiento de empuje con cada pesa rusa durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0519-7w6i0vE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0519-7w6i0vE.gif'),
('0521', 'kettlebell alternating renegade row', 'back', 'kettlebell', 'upper back', 'core', '{"core","shoulders"}', 'Comienza en posición de plancha alta con las manos sujetando las pesas rusas y los pies separados a la altura de las caderas. Activa el core y mantén el cuerpo en línea recta desde la cabeza hasta los talones. Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo. Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0521-b9kqlBy.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0521-b9kqlBy.gif'),
('0522', 'kettlebell alternating row', 'back', 'kettlebell', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y apretando los omóplatos entre sí. Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0522-Ca76jUE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0522-Ca76jUE.gif'),
('0523', 'kettlebell arnold press', 'shoulders', 'kettlebell', 'delts', 'triceps', '{"triceps","upper back"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros con las palmas hacia ti. Activa el core y empuja las pesas rusas por encima de la cabeza, girando las palmas hacia adelante mientras extiendes los brazos. Haz una pausa en la parte superior del movimiento, luego baja lentamente las pesas rusas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0523-UM8mgyG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0523-UM8mgyG.gif'),
('0524', 'kettlebell bent press', 'waist', 'kettlebell', 'abs', 'shoulders', '{"shoulders","triceps","obliques"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha. Dobla ligeramente las rodillas y empuja la pesa rusa por encima de la cabeza con el brazo derecho, manteniendo el codo bloqueado. Rota el torso hacia la izquierda, trasladando tu peso al pie izquierdo. Flexiona la rodilla izquierda y baja el torso hacia el suelo, manteniendo el brazo derecho extendido por encima de la cabeza. Mientras bajas, mantén la mirada en la pesa rusa y el pecho elevado. Cuando tu mano izquierda toque el suelo, empuja con el pie izquierdo y estira la pierna izquierda, llevando las caderas hacia adelante. Mientras llevas las caderas hacia adelante, usa el core y el brazo derecho para empujar la pesa rusa de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0524-kjE55n5.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0524-kjE55n5.gif'),
('0525', 'kettlebell bottoms up clean from the hang position', 'upper arms', 'kettlebell', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Deja que la pesa rusa cuelgue entre tus piernas, con el brazo completamente extendido. En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras tiras de la pesa rusa hacia el hombro. Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca de modo que la base de la pesa rusa quede hacia arriba. Atrapa la pesa rusa a la altura del hombro con el codo flexionado y la palma hacia arriba. Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0525-4KJEpzb.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0525-4KJEpzb.gif'),
('0526', 'kettlebell double alternating hang clean', 'upper arms', 'kettlebell', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Deja que las pesas rusas cuelguen rectas frente a tu cuerpo. En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras encoges los hombros. Mientras las pesas rusas suben, tira de ellas hacia los hombros, manteniendo los codos altos y hacia los lados. Atrapa las pesas rusas a la altura del hombro, con las palmas hacia adentro y los codos apuntando hacia adelante. Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0526-a4F9Oyc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0526-a4F9Oyc.gif'),
('0527', 'kettlebell double jerk', 'shoulders', 'kettlebell', 'delts', 'triceps', '{"triceps","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros. Flexiona ligeramente las rodillas y activa el core. Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Flexiona las rodillas y baja rápidamente a una sentadilla parcial. Extiende explosivamente las caderas y las rodillas, impulsando las pesas rusas hacia arriba. Bloquea los brazos y atrapa las pesas rusas por encima de la cabeza con las rodillas ligeramente flexionadas. Ponte de pie recto y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0527-tznL2Ad.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0527-tznL2Ad.gif'),
('0528', 'kettlebell double push press', 'shoulders', 'kettlebell', 'delts', 'triceps', '{"triceps","core"}', 'Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro. Flexiona ligeramente las rodillas y activa el core. Inicia el movimiento extendiendo explosivamente las caderas, las rodillas y los tobillos, impulsando las pesas rusas por encima de la cabeza. Cuando las pesas rusas lleguen arriba, presiónalas completamente por encima de la cabeza, bloqueando los brazos. Baja las pesas rusas a la posición inicial flexionando los codos y llevándolas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0528-I4KkPdl.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0528-I4KkPdl.gif'),
('0529', 'kettlebell double snatch', 'shoulders', 'kettlebell', 'delts', 'trapezius', '{"trapezius","forearms","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano con el brazo extendido frente a los muslos. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. En un solo movimiento explosivo, extiende las caderas, las rodillas y los tobillos, y al mismo tiempo tira de las pesas rusas hacia los hombros. Cuando las pesas rusas lleguen a la altura del hombro, rota las muñecas y lanza las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0529-M74kdvm.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0529-M74kdvm.gif'),
('0530', 'kettlebell double windmill', 'waist', 'kettlebell', 'abs', 'shoulders', '{"shoulders","hamstrings"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha. Extiende el brazo derecho por encima de la cabeza, manteniendo la mirada en la pesa rusa. Rota el pie izquierdo 45 grados hacia la izquierda y el pie derecho 90 grados hacia la derecha. Flexiona la cintura hacia la izquierda, manteniendo el brazo derecho extendido por encima de la cabeza. Baja la pesa rusa hacia el suelo, extendiéndote hacia el pie izquierdo. Haz una pausa breve, luego activa el core y empuja con el pie derecho para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0530-OaE7CpD.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0530-OaE7CpD.gif'),
('0531', 'kettlebell extended range one arm press on floor', 'chest', 'kettlebell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo. Sujeta una pesa rusa con una mano, con la palma hacia los pies. Extiende el brazo recto hacia el techo, manteniendo el codo bloqueado y la muñeca recta. Baja lentamente la pesa rusa de vuelta a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0531-rseLfH3.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0531-rseLfH3.gif'),
('0532', 'kettlebell figure 8', 'waist', 'kettlebell', 'abs', 'shoulders', '{"shoulders","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Pasa la pesa rusa entre las piernas, cambiándola de mano cuando llegue detrás de las piernas. Cuando la pesa rusa vuelva hacia adelante, pásala a la otra mano entre las piernas. Continúa pasando la pesa rusa entre las piernas con un movimiento en forma de ocho. Mantén un ritmo constante y activa el core durante todo el ejercicio. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0532-L4ay0PW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0532-L4ay0PW.gif'),
('0533', 'kettlebell front squat', 'upper legs', 'kettlebell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la pesa rusa con ambas manos frente al pecho, cerca del cuerpo. Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0533-DB0n8AG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0533-DB0n8AG.gif'),
('0534', 'kettlebell goblet squat', 'upper legs', 'kettlebell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa cerca del pecho con ambas manos. Manteniendo el pecho elevado y el core activado, baja el cuerpo a una posición de sentadilla flexionando las rodillas y las caderas. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0534-ZA8b5hc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0534-ZA8b5hc.gif'),
('0535', 'kettlebell hang clean', 'upper legs', 'kettlebell', 'hamstrings', 'glutes', '{"glutes","quadriceps","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Baja la pesa rusa hacia el suelo, dejando que se balancee entre las piernas. Extiende rápidamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro. Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con el codo pegado al cuerpo y la pesa rusa apoyada en el antebrazo. Baja la pesa rusa de vuelta a la posición inicial entre las piernas y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0535-LHWF7us.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0535-LHWF7us.gif'),
('0536', 'kettlebell lunge pass through', 'upper legs', 'kettlebell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Mientras avanzas en la zancada, pasa la pesa rusa por debajo del muslo derecho y trasládala a la mano izquierda. Empuja con el pie derecho para volver a la posición inicial, mientras pasas la pesa rusa de vuelta a la mano derecha al mismo tiempo. Repite la zancada en el lado opuesto, pasando la pesa rusa por debajo del muslo izquierdo. Continúa alternando zancadas y pasando la pesa rusa entre las manos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0536-WKMQzCD.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0536-WKMQzCD.gif'),
('0537', 'kettlebell one arm clean and jerk', 'shoulders', 'kettlebell', 'delts', 'triceps', '{"triceps","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono. Flexiona ligeramente las rodillas y inclínate desde las caderas, bajando la pesa rusa entre las piernas. Extiende explosivamente las caderas, las rodillas y los tobillos, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro. Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca y lanza la mano recta hacia arriba, bloqueando el brazo por encima de la cabeza. Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0537-vzAxBtt.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0537-vzAxBtt.gif'),
('1298', 'kettlebell one arm floor press', 'chest', 'kettlebell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo. Sujeta la pesa rusa con una mano con la palma hacia los pies y el brazo extendido recto hacia el techo. Baja lentamente la pesa rusa hacia el pecho flexionando el codo, manteniendo el brazo superior cerca del cuerpo. Haz una pausa cuando la pesa rusa esté justo encima del pecho, luego empújala de vuelta hacia arriba a la posición inicial extendiendo el codo. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1298-rg59QCH.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1298-rg59QCH.gif'),
('0538', 'kettlebell one arm jerk', 'shoulders', 'kettlebell', 'delts', 'triceps', '{"triceps","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro. Flexiona ligeramente las rodillas y activa el core. Presiona la pesa rusa por encima de la cabeza en línea recta, extendiendo el brazo por completo. Mientras presionas la pesa rusa por encima de la cabeza, flexiona las rodillas simultáneamente y estíralas rápidamente para generar impulso. Cuando la pesa rusa llegue a su punto más alto, baja rápidamente por debajo de ella flexionando las rodillas y las caderas. Atrapa la pesa rusa con una ligera flexión de rodillas y caderas, y el brazo completamente extendido por encima de la cabeza. Ponte de pie recto, extendiendo por completo las rodillas y las caderas, y estabiliza la pesa rusa por encima de la cabeza. Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y las caderas, y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0538-S37C94C.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0538-S37C94C.gif'),
('0539', 'kettlebell one arm military press to the side', 'shoulders', 'kettlebell', 'delts', 'triceps', '{"triceps","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro. Activa el core y mantén la espalda recta. Presiona la pesa rusa por encima de la cabeza, extendiendo el brazo por completo. Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0539-yCvYdi7.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0539-yCvYdi7.gif'),
('0540', 'kettlebell one arm push press', 'shoulders', 'kettlebell', 'delts', 'triceps', '{"triceps","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro. Flexiona ligeramente las rodillas y activa el core. Presiona la pesa rusa por encima de la cabeza extendiendo el brazo y estirando por completo las piernas. Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y devolviendo la pesa rusa al hombro. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0540-osdXT3K.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0540-osdXT3K.gif'),
('0541', 'kettlebell one arm row', 'back', 'kettlebell', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de la pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos. Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0541-g9AsZ8P.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0541-g9AsZ8P.gif'),
('0542', 'kettlebell one arm snatch', 'shoulders', 'kettlebell', 'delts', 'trapezius', '{"trapezius","forearms","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano entre las piernas. Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo. Extiende explosivamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hacia el hombro. Cuando la pesa rusa llegue a la altura del hombro, rota la mano y lánzala recta hacia arriba por encima de la cabeza, extendiendo el brazo por completo. Baja la pesa rusa de vuelta entre las piernas y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0542-aXcUyKb.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0542-aXcUyKb.gif'),
('0543', 'kettlebell pirate supper legs', 'shoulders', 'kettlebell', 'delts', 'triceps', '{"triceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta la pesa rusa hasta la altura del hombro, manteniendo el codo cerca del cuerpo. Extiende el brazo por completo por encima de la cabeza, enderezando el codo. Baja la pesa rusa de vuelta a la altura del hombro, luego vuelve a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0543-kuXhl0o.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0543-kuXhl0o.gif'),
('0544', 'kettlebell pistol squat', 'upper legs', 'kettlebell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos. Levanta el pie izquierdo del suelo y extiéndelo hacia adelante, manteniéndolo paralelo al suelo. Baja lentamente el cuerpo a una posición de sentadilla, manteniendo el pie derecho plano en el suelo y la pierna izquierda extendida. Haz una pausa breve en la parte baja de la sentadilla, luego empuja con el talón derecho para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0544-5bpPTHv.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0544-5bpPTHv.gif');
